<script setup>
import { ref } from 'vue'
import BackupRestorePanel from './admin/BackupRestorePanel.vue'

const props=defineProps({application:{type:Object,required:true}})
const busy=ref(false),message=ref(''),error=ref(''),fileInput=ref(null)
function requestFile(){fileInput.value?.click()}
async function backup(){busy.value=true;message.value='';error.value='';try{const payload=await props.application.exportBackup();const blob=new Blob([JSON.stringify(payload)],{type:'application/json'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`kfe-backup-${new Date().toISOString().slice(0,10)}.json`;anchor.click();URL.revokeObjectURL(url);message.value='Backup created.'}catch(e){error.value=`Backup failed: ${String(e?.message||e)}`}finally{busy.value=false}}
async function restore(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;busy.value=true;message.value='';error.value='';try{const payload=JSON.parse(await file.text());if(!payload||typeof payload!=='object')throw Error('This is not a valid KFE backup.');if(!confirm('Restore this backup? Existing local ERP data and saved configuration will be replaced by the backup.'))return;await props.application.restoreBackup(payload);message.value='Restore complete. Reloading KFE…';setTimeout(()=>location.reload(),700)}catch(e){error.value=`Restore failed: ${String(e?.message||e)}`}finally{busy.value=false}}
async function resetData(){if(!confirm('RESET ALL KFE BUSINESS DATA? Saved configuration defaults in Settings will remain.'))return;if(!confirm('Final confirmation: erase trips, shifts, fuel, payments, and other business records? Saved configuration defaults will remain.'))return;busy.value=true;message.value='';error.value='';try{await props.application.resetAllData();message.value='Business data reset. Saved configuration retained. Reloading…';setTimeout(()=>location.reload(),500)}catch(e){error.value=`Reset failed: ${String(e?.message||e)}`;busy.value=false}}
</script>
<template>
<section class="kfe-settings-page" aria-labelledby="settings-title"><header class="kfe-page-head"><span class="kfe-eyebrow">ADMIN SETTINGS</span><h1 id="settings-title">Settings</h1><p>Manage backups and reset business activity. Saved configuration defaults remain separate from resettable records.</p></header>
<div v-if="error" class="kfe-alert is-error" role="alert">{{error}}</div><div v-if="message" class="kfe-alert is-ok" role="status">✓ {{message}}</div>
<section class="kfe-settings-card" aria-labelledby="offline-maps-title"><span class="kfe-card-kicker">OFFLINE ROUTING</span><h2 id="offline-maps-title">Offline Maps</h2><p>Download and manage regional Valhalla road-routing packages stored locally on this phone.</p><router-link class="kfe-action-link" to="/offline-maps" aria-label="Open Offline Maps to download or manage regional maps">Download / Manage Offline Maps</router-link></section>
<section class="kfe-settings-card" aria-labelledby="backup-title"><span class="kfe-card-kicker">BACKUP</span><h2 id="backup-title">Backup &amp; restore</h2><p>Manage local recovery copies, portable exports, and the Dropbox connection for cloud backups.</p><BackupRestorePanel /></section>
<section class="kfe-settings-card danger" aria-labelledby="reset-title"><span class="kfe-card-kicker">BUSINESS DATA</span><h2 id="reset-title">Reset business data</h2><p>Erase trips, shifts, fuel logs, payments, and other operational records. Saved settings and defaults are retained.</p><button class="kfe-action-danger" :disabled="busy" @click="resetData">Reset business data</button></section>
</section>
<style scoped>
.kfe-settings-page{display:grid;gap:14px;padding:18px 16px 112px;max-width:720px;margin:auto}.kfe-page-head{display:grid;gap:5px;padding:2px 2px 4px}.kfe-page-head h1{margin:0;font-size:clamp(1.75rem,7vw,2.15rem);letter-spacing:-.03em}.kfe-page-head p,.kfe-settings-card p{margin:0;color:var(--kfe-muted-text);line-height:1.45}.kfe-settings-card{background:var(--kfe-ui-surface);border:1px solid var(--kfe-ui-border);border-radius:20px;padding:18px;box-shadow:var(--kfe-ui-shadow);display:grid;gap:11px}.kfe-settings-card h2{margin:0;font-size:1.05rem}.kfe-card-kicker{font-size:.67rem;text-transform:uppercase;letter-spacing:.1em;font-weight:900;color:var(--kfe-accent)}.kfe-settings-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px}.kfe-settings-actions button,.kfe-action-danger{min-height:52px;border-radius:14px;padding:0 14px;font-weight:900}.kfe-action-primary{border:0;background:var(--kfe-accent);color:var(--kfe-on-accent)}.kfe-action-link{display:flex;align-items:center;justify-content:center;min-height:48px;border-radius:14px;padding:0 14px;font-weight:900;text-decoration:none;background:var(--kfe-accent);color:var(--kfe-on-accent)}.kfe-action-secondary{border:1px solid var(--kfe-ui-border);background:var(--kfe-ui-bg);color:var(--kfe-ui-text)}.kfe-action-danger{border:1px solid var(--kfe-danger);background:transparent;color:var(--kfe-danger);width:100%}.danger{border-color:color-mix(in srgb,var(--kfe-danger) 40%,var(--kfe-ui-border))}.kfe-alert{padding:12px 14px;border-radius:14px;font-weight:700}.is-error{background:color-mix(in srgb,var(--kfe-danger) 14%,var(--kfe-ui-surface));color:var(--kfe-danger)}.is-ok{background:color-mix(in srgb,var(--kfe-success) 14%,var(--kfe-ui-surface));color:var(--kfe-success)}@media(max-width:480px){.kfe-settings-actions{grid-template-columns:1fr}.kfe-settings-card{padding:16px}}
</style>
